#include "semantic/semantic.hpp"
#include <stdexcept>
namespace nexus {
void SemanticAnalyzer::analyze(Program& p){for(auto& f:p.functions){if(funcs_.contains(f.name))throw std::runtime_error("duplicate function: "+f.name);funcs_[f.name]=&f;}for(auto& f:p.functions){std::unordered_map<std::string,Type> env;for(auto& a:f.params)env[a.name]=a.type;block(*f.body,env,f.ret);}}
Type SemanticAnalyzer::expr(Expr* e,std::unordered_map<std::string,Type>& env){if(dynamic_cast<IntExpr*>(e))return Type::i64();if(dynamic_cast<BoolExpr*>(e))return Type::boolean();if(dynamic_cast<StringExpr*>(e))return Type::string();if(auto*v=dynamic_cast<VarExpr*>(e)){if(!env.contains(v->name))throw std::runtime_error("unknown variable: "+v->name);return env[v->name];}if(auto*u=dynamic_cast<UnaryExpr*>(e)){auto t=expr(u->rhs.get(),env);if(u->op==TokenKind::Minus&&t.kind!=TypeKind::I64)throw std::runtime_error("unary '-' requires i64");if(u->op==TokenKind::Bang&&t.kind!=TypeKind::Bool)throw std::runtime_error("'!' requires bool");return t;}if(auto*b=dynamic_cast<BinaryExpr*>(e)){auto l=expr(b->lhs.get(),env),r=expr(b->rhs.get(),env);if(l.kind!=r.kind)throw std::runtime_error("binary operands have different types");switch(b->op){case TokenKind::Plus:case TokenKind::Minus:case TokenKind::Star:case TokenKind::Slash:case TokenKind::Percent:if(l.kind!=TypeKind::I64)throw std::runtime_error("arithmetic requires i64");return l;case TokenKind::EqualEqual:case TokenKind::BangEqual:case TokenKind::Less:case TokenKind::LessEqual:case TokenKind::Greater:case TokenKind::GreaterEqual:return Type::boolean();case TokenKind::AndAnd:case TokenKind::OrOr:if(l.kind!=TypeKind::Bool)throw std::runtime_error("logical operators require bool");return Type::boolean();default:break;}}if(auto*c=dynamic_cast<CallExpr*>(e)){if(c->callee=="print"){if(c->args.size()!=1)throw std::runtime_error("print expects one argument");expr(c->args[0].get(),env);return Type::void_();}if(!funcs_.contains(c->callee))throw std::runtime_error("unknown function: "+c->callee);auto*f=funcs_[c->callee];if(f->params.size()!=c->args.size())throw std::runtime_error("wrong argument count for "+c->callee);for(size_t i=0;i<c->args.size();++i){auto t=expr(c->args[i].get(),env);if(t.kind!=f->params[i].type.kind)throw std::runtime_error("argument type mismatch in "+c->callee);}return f->ret;}throw std::runtime_error("unsupported expression");}
void SemanticAnalyzer::block(Block& b,std::unordered_map<std::string,Type>& env,Type ret){for(auto&s:b.statements){if(auto*l=dynamic_cast<LetStmt*>(s.get())){if(env.contains(l->name))throw std::runtime_error("duplicate variable: "+l->name);auto t=expr(l->init.get(),env);if(l->type.kind!=TypeKind::Unknown&&l->type.kind!=t.kind)throw std::runtime_error("type mismatch for "+l->name);l->type=t;env[l->name]=t;}else if(auto*e=dynamic_cast<ExprStmt*>(s.get())){expr(e->expr.get(),env);}else if(auto*r=dynamic_cast<ReturnStmt*>(s.get())){auto t=r->expr?expr(r->expr.get(),env):Type::void_();if(t.kind!=ret.kind)throw std::runtime_error("return type mismatch");}else if(auto*i=dynamic_cast<IfStmt*>(s.get())){auto t=expr(i->cond.get(),env);if(t.kind!=TypeKind::Bool)throw std::runtime_error("if condition must be bool");auto e1=env;block(*i->thenBlock,e1,ret);if(i->elseBlock){auto e2=env;block(*i->elseBlock,e2,ret);}}else if(auto*w=dynamic_cast<WhileStmt*>(s.get())){auto t=expr(w->cond.get(),env);if(t.kind!=TypeKind::Bool)throw std::runtime_error("while condition must be bool");auto e=env;block(*w->body,e,ret);}}}
}
